"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["56879"],{76255(e){e.exports=JSON.parse('{"id":"FIN-086","slug":"bankruptcy","term":"Bankruptcy","also_known_as":[],"difficulty":"Beginner","definition":"Bankruptcy is a legal process for people or businesses that cannot repay their debts. It allows debts to be reorganised or wiped out, usually in exchange for giving up some assets and accepting restrictions.","explanation":["When debts become far larger than a person\'s or company\'s ability to repay, bankruptcy offers a structured way out. A court or official process takes control, decides how available assets will be shared among creditors and, in many cases, releases the debtor from remaining debts.","There are two broad approaches. In liquidation, the debtor\'s assets are sold and the money is divided among creditors, after which most remaining debts are cancelled. In reorganisation, the debtor keeps operating, especially in the case of a business, while repaying creditors under a new plan over several years.","Bankruptcy has serious effects. It usually stays on a credit record for many years, makes borrowing difficult and expensive, and may restrict certain activities, such as running a company. Some debts, such as certain taxes, fines or student loans in some countries, may not be wiped out.","The rules, names and consequences differ greatly between countries. Bankruptcy is generally considered a last resort after options such as negotiating with creditors or entering a debt repayment plan."],"note":"","total":1500,"prev":{"slug":"bank-transfer","term":"Bank Transfer"},"next":{"slug":"bankruptcy-cost","term":"Bankruptcy Cost"}}')}}]);